from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
X = partial(mk, "paraphilic", "paraphilic", "scale")
DSM_X = DSM("Paraphilic Disorders")
SIN_US = src("src-stop-it-now-us", "How can I find confidential help?", "Stop It Now! (US)", "https://stopitnow.org/node/1612", seen=True)
SIN_UK = src("src-stop-it-now-uk", "Stop It Now helpline 0808 1000 900", "Lucy Faithfull Foundation (UK)", "https://www.stopitnow.org.uk/", seen=True, note="Hours from directory listings.")
TFC = src("src-talking-for-change", "Talking for Change (CAMH, Public Safety Canada)", "findahelpline.com listing", "https://findahelpline.com/organizations/talking-for-change", seen=True)
MOORE = src("src-moore-center", "Resources for people concerned about their sexual thoughts", "Moore Center for the Prevention of Child Sexual Abuse, Johns Hopkins", "https://publichealth.jhu.edu/moore-center-for-the-prevention-of-child-sexual-abuse/get-support/resources-for-people-concerned-about-their-sexual-thoughts", seen=True)
CZECH = src("src-czech-paraphilia", "The Prevalence of Paraphilic Interests in the Czech Population", "National Institute of Mental Health (Czechia), Parafilik project", "https://parafilik.nudz.cz/wp-content/uploads/2023/12/The-Prevalence-of-Paraphilic-Interests-in-the-Czech-Population.pdf", seen=True, note="Not opened.")
X_NOTE = ["Strictly non-sensational: no descriptions of acts, no victim-blaming, no eroticised language.", "Clear line between consensual adult interests (not a disorder) and non-consent or harm (always wrong, regardless of diagnosis)."]
GEN_COMMS = ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia"]
PREV_COMMS = ["stop-it-now-us", "stop-it-now-uk", "talking-for-change-canada"]

CARDS.append(X("paraphilic-disorders-overview", "Paraphilic Disorders (overview)", "Unusual sexual interests, and when they become a problem", ["paraphilias", "atypical sexual interests"], "n/a (F65.x by type)",
 "Intense, unusual sexual interests that count as a disorder only when they cause distress, harm, or involve non-consent.",
 "A paraphilia is a strong, persistent sexual interest in something outside the usual range. Having one is not a mental disorder, and many people enjoy unusual interests privately or with consenting adults. It becomes a paraphilic disorder only when it causes real distress or problems, or when acting on it harms or risks harming someone who hasn't consented or can't consent. Consent and harm are the whole point of this chapter. Asking for help is responsible, not shameful.",
 ["I spent years thinking my interests made me a bad person. A therapist helped me see the question was never what I feel, but what I do.", "The hardest call I ever made was to a helpline. They were kind. They helped me keep everyone safe, including me."],
 ["A strong, lasting sexual interest outside the usual range (six months or more)", "Disorder only if it causes distress or impairment, or involves harm or non-consent", "Interests enjoyed privately or with consenting adults are not a disorder", "Urges toward non-consenting people are a reason to seek help now"],
 [{"myth": "Any unusual sexual interest is a mental illness.", "fact": "The DSM is explicit that a paraphilia alone is not a disorder. Distress, impairment, or harm to others is what makes the diagnosis."},
  {"myth": "People with these interests can't control their behaviour.", "fact": "Interests and actions are different. Most people with atypical interests never harm anyone, and treatment helps people who worry they might."},
  {"myth": "Seeking help will get you arrested.", "fact": "Confidential helplines and clinics exist specifically for people worried about their thoughts who have not harmed anyone. Rules on confidentiality vary by country, and helplines explain them up front."}],
 {"plain": "Unusual sexual interests are common; one general-population study found some paraphilic interests in a sizeable minority of adults. Paraphilic disorders, where there is distress or harm, are much rarer and poorly counted.", "figure": "Prevalence of paraphilic disorders not well established; interest surveys show combined rates in the teens of percent for some interests (Czech population study)", "source_ref": "src-czech-paraphilia", "note": "Needs a primary citation; most data come from clinical or forensic samples."},
 {"plain_summary": "Treatment is for distress or risk, not for the interest itself. Cognitive behavioural therapy helps people manage urges, challenge thinking that excuses harm, build relationships and coping, and make safety plans. For people at risk of harming others, specialist clinics add structured risk management and, in some cases, medication that lowers sex drive, prescribed and monitored by a doctor with informed consent. Co-occurring depression, substance use, or trauma are treated. Prevention programmes exist for people who are worried and have not offended.",
  "evidence_based_options": ["CBT focused on urge management, thinking patterns, and relapse prevention", "Specialist assessment and risk management for people worried about harming others", "Medication to reduce sex drive in selected cases, prescribed and monitored by a doctor", "Treatment of co-occurring depression, substance use, or trauma"],
  "self_help_that_supports_care": ["Separating what you feel from what you do; only actions can harm", "Calling a confidential prevention helpline if you're worried about your thoughts", "Avoiding alcohol and situations that lower your control", "Telling a professional before anything happens, not after"],
  "guideline_refs": ["src-moore-center"]},
 "If your sexual interests cause you distress, or you're worried you might act in a way that harms someone, especially a child or someone who can't consent, contact a confidential prevention helpline or a doctor now. If someone has been harmed, their safety comes first: contact child protection or emergency services.",
 "Consensual adult kink, fetishes, and fantasies that harm no one aren't disorders. Being gay, bisexual, or transgender has nothing to do with this chapter. Sexual offending without a paraphilia is a legal matter, not a diagnosis.",
 "People with unwanted urges can live safe, honest lives. Reaching out before harm happens is possible, and it works.",
 ["courtship-paraphilic-disorders", "sexual-masochism-and-sadism-disorders", "pedophilic-disorder", "fetishistic-and-transvestic-disorders", "antisocial-personality-disorder"],
 ["paraphilia-vs-paraphilic-disorder", "consent-and-minors", "limits-of-confidentiality", "cbt", "relapse-prevention"],
 PREV_COMMS + GEN_COMMS, ("Soft line illustration of a person on a phone call sitting on a bench in a quiet park, shoulders relaxed, a path leading toward a lit building. Pastel grey-blue and gold.", "A person makes a phone call on a quiet park bench, a path leading toward a lit building."),
 [DSM_X, MOORE, CZECH, SIN_US], qs=["Find a primary prevalence source.", "Forensic clinician to review."], sens="elevated", notes=X_NOTE, clin=True, card_type="explainer"))

CARDS.append(X("courtship-paraphilic-disorders", "Voyeuristic, Exhibitionistic, and Frotteuristic Disorders", "Watching, exposing, or touching without consent", ["courtship disorders", "voyeurism", "exhibitionism", "frotteurism"], "F65.3 / F65.2 / F65.81",
 "Sexual urges to watch, expose yourself to, or touch people who haven't consented, acted on or causing distress.",
 "These three disorders involve sexual arousal from things done to people who haven't agreed: secretly watching someone undressing or being intimate (voyeuristic), exposing one's genitals to an unsuspecting person (exhibitionistic), or touching or rubbing against a non-consenting person (frotteuristic). They're diagnosed when a person has acted on the urges, or the urges cause real distress, over six months or more. They usually begin in the teens. The behaviour is illegal and harms its targets. Treatment helps people stop.",
 ["I told myself it wasn't hurting anyone. Then I read what it did to the people I'd done it to, and I called for help.", "Being watched without knowing left me checking every window for years. I want people who do this to know that."],
 ["Recurring arousal from watching, exposing to, or touching non-consenting people", "Acting on the urges, or urges causing distress or problems, for six months or more", "Usually starts in the teens; more often diagnosed in men", "Shame, secrecy, and fear of consequences"],
 [{"myth": "Flashing or peeping is a harmless prank.", "fact": "It's a sexual offence that frightens and harms people, and it can escalate. Treating it as a joke protects nobody."},
  {"myth": "Nothing can be done; people like this just reoffend.", "fact": "Specialist CBT and risk management reduce reoffending, and many people stop for good once they get help."}],
 {"plain": "Good population figures are scarce. In anonymous surveys, a minority of men report some arousal to watching or exposing; the disorders, with acting out or distress, are much rarer.", "figure": "Prevalence not well established; voyeuristic disorder may be the most common paraphilic disorder (DSM-5-TR text)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "Treatment uses CBT to recognise the chain of thoughts, situations, and feelings that lead to the behaviour, to challenge the excuses that allow it, to build empathy for the people affected, and to plan how to avoid and interrupt it. Specialist services add risk assessment and, for some, medication that lowers sex drive, prescribed and monitored by a doctor. Alcohol and substance use are addressed, as they lower control. Treatment is often court-mandated, but people can and do seek it voluntarily, which usually goes better.",
  "evidence_based_options": ["CBT with relapse-prevention planning", "Specialist forensic or sexual behaviour clinics", "Medication to reduce sex drive in selected cases, prescribed and monitored by a doctor", "Treatment of substance use and co-occurring conditions"],
  "self_help_that_supports_care": ["Noticing the build-up and leaving the situation early", "Avoiding alcohol and places where the behaviour happened", "Calling a prevention helpline before acting, not after", "Being honest with a therapist about urges and near-misses"],
  "guideline_refs": ["src-moore-center"]},
 "If you've been watching, exposing yourself to, or touching people without consent, or you're worried you will, get help now from a doctor, a sexual behaviour clinic, or a confidential helpline. If you've been on the receiving end, it wasn't your fault; you can report it and seek support.",
 "Consensual exhibitionism or voyeurism between adults who have agreed, such as at adult venues or in private, isn't a disorder.",
 "People who seek help before being caught, and those who go through treatment after, can stop. Their families and communities become safer, and so do they.",
 ["paraphilic-disorders-overview", "sexual-masochism-and-sadism-disorders", "pedophilic-disorder", "antisocial-personality-disorder", "alcohol-use-disorder"],
 ["paraphilia-vs-paraphilic-disorder", "relapse-prevention", "cbt", "limits-of-confidentiality"],
 PREV_COMMS + GEN_COMMS, ("Soft line illustration of a person crossing a street toward a counselling centre with a small sign, autumn trees, calm light. Pastel grey-blue and amber.", "A person crosses a street toward a counselling centre with a small sign."),
 [DSM_X, MOORE, SIN_UK], qs=["Find a primary prevalence source.", "Forensic clinician to review."], sens="elevated", notes=X_NOTE, clin=True))

CARDS.append(X("sexual-masochism-and-sadism-disorders", "Sexual Masochism and Sexual Sadism Disorders", "When pain or power in sex causes distress or harms others", ["masochism", "sadism", "BDSM (consensual practice, not a disorder)"], "F65.51 / F65.52",
 "Arousal from receiving or inflicting pain or humiliation, diagnosed only when it distresses the person or harms non-consenting people.",
 "Sexual masochism is arousal from being hurt or humiliated; sexual sadism is arousal from another person's pain. Many adults enjoy consensual play with pain, restraint, or power. That's within adult sexuality and not a disorder. Masochism disorder is diagnosed only when the interest causes real distress or involves dangerous practices. Sadism disorder is diagnosed when a person has acted on it with someone who hasn't consented, or the urges cause distress. Consent is the dividing line.",
 ["The clinician didn't flinch when I described what I'm into. She asked whether it was safe and whether I was happy. It was and I am. No diagnosis.", "My urges scared me because I didn't want to hurt anyone who hadn't asked. Therapy gave me a place to say that out loud."],
 ["Recurring arousal from being hurt (masochism) or from another's pain (sadism)", "Disorder only if it causes distress or impairment, or involves a non-consenting person", "Lasting six months or more", "Dangerous solo practices that risk injury count as a reason for concern"],
 [{"myth": "Anyone into BDSM has a mental disorder.", "fact": "The DSM says consensual activity between adults that causes no distress is not a disorder. Studies suggest people who practise consensual BDSM are no less mentally healthy than others."},
  {"myth": "Sadism means someone is a violent criminal.", "fact": "Sadistic interests enjoyed consensually harm no one. The disorder is about non-consent or distress, which is a very different thing."}],
 {"plain": "Interest in consensual power or pain play is fairly common among adults. Sexual sadism disorder, defined by non-consent, is rare and mostly seen in forensic settings.", "figure": "Prevalence of the disorders not well established; interest surveys show a sizeable minority of adults report some interest (Czech population study)", "source_ref": "src-czech-paraphilia", "note": "Needs a primary citation."},
 {"plain_summary": "For consensual interests that cause distress, therapy focuses on reducing shame, safety, and relationships, not on removing the interest. Where there's a risk to others, specialist services provide CBT, risk management, and in some cases medication to reduce sex drive, prescribed and monitored by a doctor. A clinician who understands kink without judgement makes a big difference, and such clinicians exist.",
  "evidence_based_options": ["Kink-aware therapy for distress, safety, and relationships", "Specialist assessment and CBT where there is risk to non-consenting people", "Medication to reduce sex drive in selected cases, prescribed and monitored by a doctor", "Treatment of co-occurring depression, anxiety, or substance use"],
  "self_help_that_supports_care": ["Consent, communication, and safety practices with partners", "Avoiding solo practices that restrict breathing or risk injury", "Finding a kink-aware clinician if the interest causes distress", "Calling a prevention helpline if urges involve anyone who hasn't consented"],
  "guideline_refs": ["src-moore-center"]},
 "If your interests cause you distress, involve practices that could seriously injure you, or involve urges toward people who haven't consented, talk to a kink-aware therapist, a doctor, or a confidential helpline. If a partner is pushing past your consent, that's abuse, and support is available.",
 "Consensual BDSM between adults, with communication and safety, isn't a disorder. Being hurt by a partner who ignores your consent isn't masochism; it's abuse.",
 "People find clinicians who understand them, drop the shame, and keep themselves and their partners safe.",
 ["paraphilic-disorders-overview", "fetishistic-and-transvestic-disorders", "partner-violence-and-adult-abuse", "nonsuicidal-self-injury"],
 ["paraphilia-vs-paraphilic-disorder", "consent-and-minors", "boundaries", "stigma"],
 GEN_COMMS, ("Soft line illustration of two adults talking at a kitchen table over coffee, relaxed, a notebook between them, morning light. Pastel grey-blue and plum.", "Two adults talk over coffee at a kitchen table."),
 [DSM_X, CZECH, MOORE], qs=["Find a primary prevalence source.", "Clinician with kink-awareness training to review."], sens="elevated", notes=X_NOTE, clin=True))

CARDS.append(X("pedophilic-disorder", "Pedophilic Disorder", "Attraction to children, and help before anyone is harmed", ["paedophilic disorder (UK spelling)", "minor-attracted (community term, contested)"], "F65.4",
 "Persistent sexual attraction to prepubescent children, acted on or causing distress, in an adult. Help exists before harm.",
 "Pedophilic disorder is a persistent sexual attraction to children who haven't reached puberty, in someone aged 16 or older, that the person has acted on or that causes them distress. The attraction isn't chosen. Acting on it is always abuse and always wrong. Not everyone with this attraction offends, and not everyone who abuses children has it. Confidential help exists for people who are worried about their thoughts and want to make sure they never harm a child.",
 ["I have never touched a child and I never will. For years I thought that meant I had to carry this alone. A helpline proved me wrong.", "What happened to me as a child was done by someone who told himself it was love. It was not. Prevention matters to survivors like me."],
 ["Persistent sexual attraction to prepubescent children, for six months or more", "In a person aged 16 or older, at least five years older than the child", "Acted on, or causing the person distress or difficulty", "Secrecy, shame, isolation; often depression"],
 [{"myth": "Everyone with this attraction will abuse a child.", "fact": "Many people with the attraction never offend and go to great lengths not to. Prevention programmes exist because help before harm works."},
  {"myth": "Child abusers are always strangers with this disorder.", "fact": "Most abuse is by someone the child knows, and many abusers don't have a persistent attraction to children. Both facts matter for keeping children safe."},
  {"myth": "Asking for help means being reported and arrested.", "fact": "Confidential prevention helplines exist for people who have not harmed a child. They explain their confidentiality rules at the start of the call."}],
 {"plain": "Reliable numbers are hard to get because of stigma. Studies suggest a small percentage of adult men have some sexual attraction to children; the disorder, with acting out or distress, is less common still.", "figure": "Estimates around 3%–5% of adult men with some attraction, with a wide range across studies (DSM-5-TR text suggests prevalence of the disorder is unknown but likely a few percent at most)", "source_ref": "src-dsm", "note": "Needs a primary citation; figures contested."},
 {"plain_summary": "Treatment aims to prevent harm and reduce suffering. CBT helps people manage urges, challenge thoughts that could justify harm, build adult relationships and support, and make detailed plans to avoid risky situations. Some people choose medication that lowers sex drive, prescribed and monitored by a doctor with informed consent. Depression, isolation, and substance use are treated. Prevention programmes in the US, UK, Canada, and Germany offer confidential support and therapy to people who have not offended.",
  "evidence_based_options": ["CBT focused on urge management, thinking patterns, and risk-avoidance planning", "Prevention programmes for people who have not offended", "Medication to reduce sex drive in selected cases, prescribed and monitored by a doctor", "Treatment of depression, isolation, and substance use"],
  "self_help_that_supports_care": ["Calling a confidential prevention helpline; this is what they're for", "Never being alone with children, and saying no to roles that involve them", "Avoiding any sexual material involving children; viewing it is abuse and a crime", "Building adult relationships and a life that isn't lived in secret"],
  "guideline_refs": ["src-moore-center"]},
 "If you're attracted to children and want to make sure you never harm one, contact a confidential prevention helpline today; they will not judge you. If you have harmed a child, or a child is at risk right now, contact child protection or emergency services; the child's safety comes first. If you were abused as a child, support lines exist for you too.",
 "Attraction to adults who look young, or to teenagers past puberty, isn't pedophilic disorder, though sexual contact with anyone under the age of consent is still a crime. Being gay has nothing to do with this.",
 "People with this attraction who get help describe lives that are no longer secret, and children who are safer because they reached out.",
 ["paraphilic-disorders-overview", "child-abuse-and-neglect", "major-depressive-disorder", "antisocial-personality-disorder", "posttraumatic-stress-disorder"],
 ["paraphilia-vs-paraphilic-disorder", "consent-and-minors", "limits-of-confidentiality", "relapse-prevention", "stigma"],
 PREV_COMMS, ("Soft line illustration of a person sitting in a quiet room dialling a phone, a calendar on the wall, a window with daylight. Pastel grey-blue and soft gold. No children depicted.", "A person sits in a quiet room dialling a phone."),
 [DSM_X, SIN_US, SIN_UK, TFC, MOORE], qs=["Find a primary prevalence source.", "Forensic clinician and survivor advocate to review wording."], sens="elevated", notes=X_NOTE + ["Illustration must not depict children.", "Crisis strip required: the card speaks to people with the attraction and to survivors."], clin=True))

CARDS.append(X("fetishistic-and-transvestic-disorders", "Fetishistic and Transvestic Disorders", "When an object or cross-dressing brings distress", ["fetishism", "transvestism (outdated as a general term)"], "F65.0 / F65.1",
 "Arousal from objects, body parts, or cross-dressing, diagnosed only when it causes real distress or problems.",
 "Fetishistic disorder involves intense arousal from non-living objects or from a specific non-genital body part. Transvestic disorder involves arousal from cross-dressing. Both are common as interests and harm no one, so neither is a disorder unless it causes real distress or problems, such as guilt, damaging secrecy, or needing it to the exclusion of everything else. Cross-dressing is not the same as being transgender. These diagnoses are rare, and therapy focuses on shame and relationships, not on removing the interest.",
 ["My partner found out and we had the hardest conversation of our marriage. Couples therapy helped us both understand it. We're fine now.", "I used to feel disgusted with myself after. The therapist asked who I was hurting. The answer was only me, with the shame."],
 ["Recurring arousal from objects, non-genital body parts, or cross-dressing", "Lasting six months or more", "Disorder only if causing distress, impairment, or relationship harm", "Shame, secrecy, or conflict with a partner are usually the real problem"],
 [{"myth": "Having a fetish means something is wrong with you.", "fact": "Fetishes are common and harmless. The DSM only calls it a disorder when it causes real distress or problems."},
  {"myth": "Men who cross-dress are gay or transgender.", "fact": "Most people with transvestic interests are heterosexual men who identify as men. Gender identity, sexual orientation, and cross-dressing are three different things."}],
 {"plain": "Fetishistic and cross-dressing interests are common; the disorders, defined by distress, are rare and rarely diagnosed.", "figure": "Prevalence of the disorders not established; fetishism was among the most commonly reported interests in a Czech population study", "source_ref": "src-czech-paraphilia", "note": "Needs a primary citation."},
 {"plain_summary": "Therapy aims to reduce shame and distress, improve communication with partners, and help the person integrate the interest into a life and relationships they're happy with. Couples therapy often helps. Treating depression or anxiety matters. There's no good reason to try to eliminate a harmless interest, and attempts to do so tend to fail and increase distress.",
  "evidence_based_options": ["Sex-positive or kink-aware psychotherapy for shame and distress", "Couples or relationship therapy", "Treatment of co-occurring depression or anxiety", "Psychoeducation for the person and partner"],
  "self_help_that_supports_care": ["Learning how common these interests are", "Honest conversation with a partner at the right time, with support if needed", "Noticing whether the distress is the interest or the secrecy", "Finding a clinician who won't be shocked"],
  "guideline_refs": []},
 "If an interest in objects or cross-dressing is causing you distress, guilt, or relationship problems, a sex-positive therapist can help. If you think your feelings about cross-dressing are about who you are rather than arousal, the gender dysphoria card may be more relevant.",
 "Enjoying a fetish or cross-dressing without distress isn't a disorder. Being transgender or gender non-conforming is not transvestic disorder. Using objects designed for sex isn't fetishism.",
 "Most people find the problem was the shame, not the interest, and that shame can be set down.",
 ["paraphilic-disorders-overview", "sexual-masochism-and-sadism-disorders", "gender-dysphoria", "generalized-anxiety-disorder"],
 ["paraphilia-vs-paraphilic-disorder", "gender-identity", "stigma", "therapy"],
 GEN_COMMS, ("Soft line illustration of a person folding laundry calmly on a bed, sunlight on the quilt, a partner reading nearby. Pastel grey-blue and rose.", "A person folds laundry calmly on a sunlit bed while a partner reads nearby."),
 [DSM_X, CZECH], qs=["Find a primary prevalence source."], sens="elevated", notes=X_NOTE))
